// Security regression tests for the RouterOS scripts generated by
// utils/routerProvision.js. These exercise the REAL generators (the module is
// not mocked) while mocking DB / wireguard / logger / encryption / identity so
// no external resources are touched.

process.env.ROUTER_REGISTRATION_SECRET = 'test-registration-secret';
process.env.PUBLIC_BASE_URL = 'https://example.test';
delete process.env.MIKROTIK_API_PASSWORD;
delete process.env.HOTSPOT_ADMIN_PASSWORD;

jest.mock('../config/database', () => ({
    execute: jest.fn(async () => [[]]),
    query: jest.fn(async () => [[]])
}));

jest.mock('../utils/logger', () => ({
    info: jest.fn(), warn: jest.fn(), error: jest.fn(), debug: jest.fn()
}));

jest.mock('../utils/wireguard', () => ({
    generateKeyPair: jest.fn(() => ({ publicKey: 'PUB', privateKey: 'PRIV' })),
    generatePresharedKey: jest.fn(() => 'PSK'),
    getNextAvailableIp: jest.fn(async () => '10.7.0.5'),
    saveRouterWireGuard: jest.fn(),
    addPeerToServer: jest.fn(async () => ({ success: true })),
    ensureServerKeys: jest.fn(() => ({ publicKey: 'SERVERPUBKEY' })),
    listenPort: 51820,
    networkCidr: '10.7.0.0/16',
    serverIp: '10.7.0.1'
}));

jest.mock('../utils/encryption', () => ({ encrypt: (v) => `enc:${v}` }));

jest.mock('../utils/routerIdentity', () => ({
    resolveRouterIdentity: jest.fn(),
    normalizeRouterId: (v) => v
}));

const routerProvision = require('../utils/routerProvision');

describe('generateBootstrapScript security', () => {
    const script = routerProvision.generateBootstrapScript();

    test('uses HTTPS with certificate verification and never HTTP fallback', () => {
        expect(script).toContain('mode=https check-certificate=yes');
        expect(script).not.toMatch(/mode=http\b/);
        expect(script).not.toContain('check-certificate=no');
    });

    test('does not send auto_connect (registration must stay pending)', () => {
        expect(script).not.toContain('auto_connect=1');
    });

    test('removes a stale download before fetching', () => {
        const removeIdx = script.indexOf('/file remove [find name="universal-bootstrap.rsc"]');
        const fetchIdx = script.indexOf('/tool fetch url=$hbRegUrl');
        expect(removeIdx).toBeGreaterThan(-1);
        expect(fetchIdx).toBeGreaterThan(-1);
        expect(removeIdx).toBeLessThan(fetchIdx);
    });

    test('validates the downloaded size before importing', () => {
        const sizeIdx = script.indexOf(':if ($fileSize < 100)');
        const importIdx = script.indexOf('/import file-name="universal-bootstrap.rsc"');
        expect(sizeIdx).toBeGreaterThan(-1);
        expect(importIdx).toBeGreaterThan(-1);
        expect(sizeIdx).toBeLessThan(importIdx);
    });
});

describe('generateWaitScript security', () => {
    const script = routerProvision.generateWaitScript({
        routerID: 'RT-1', routerName: 'Site', assignedIp: '10.7.0.5'
    });

    test('poll and heartbeat fetches verify TLS and never use HTTP', () => {
        expect(script).toContain('mode=https check-certificate=yes');
        expect(script).not.toMatch(/mode=http\b/);
        expect(script).not.toContain('check-certificate=no');
    });

    test('removes the temp file before fetching so a stale file is never imported', () => {
        const removeIdx = script.indexOf('/file remove $tmp');
        const fetchIdx = script.indexOf('/tool fetch url=$hbPollUrl');
        expect(removeIdx).toBeGreaterThan(-1);
        expect(fetchIdx).toBeGreaterThan(-1);
        expect(removeIdx).toBeLessThan(fetchIdx);
    });
});

describe('generateProvisionScript secret handling', () => {
    const script = routerProvision.generateProvisionScript({
        router: { router_name: 'Site A', ssid: 'HotBando-Free-WiFi' },
        routerID: 'RT-1',
        assignedIp: '10.7.0.5',
        wireguard: {
            routerPublicKey: 'PUB',
            routerPrivateKey: 'PRIV',
            serverPublicKey: 'SERVERPUBKEY',
            presharedKey: 'PSK'
        }
    });

    test('never embeds a hardcoded API password', () => {
        expect(script).not.toContain('HotBandoApi2024');
        // With MIKROTIK_API_PASSWORD unset the API user is not created.
        expect(script).not.toMatch(/\/user add name="hotbando-api"/);
    });

    test('never embeds a hardcoded hotspot admin password', () => {
        expect(script).not.toContain('hotbando2024');
        expect(script).not.toMatch(/\/ip hotspot user add name="admin"/);
    });
});
